using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

namespace Acme.Ticketing.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddTicketingInfrastructure(
        this IServiceCollection services, Action<DbContextOptionsBuilder> configureDatabase)
    {
        services.AddDbContext<TicketingDbContext>(configureDatabase);
        services.AddScoped<IUnitOfWork, UnitOfWork>();
        services.AddScoped<IVenueRepository, VenueRepository>();
        services.AddScoped<IShowRepository, ShowRepository>();
        services.AddScoped<IBookingRepository, BookingRepository>();
        return services;
    }

    /// <summary>Creates the schema if it does not exist.</summary>
    public static void EnsureTicketingDatabase(this IServiceProvider services)
    {
        using var scope = services.CreateScope();
        scope.ServiceProvider.GetRequiredService<TicketingDbContext>().Database.EnsureCreated();
    }
}
